// 1. Grab the current item data
const item = $json;

// 2. Try to find the post text. 
// It looks in the current node first, then falls back to the 'executor' node.
const postContent = item.output || $('executor').item.json.output;

// 3. Check if we actually found something
if (!postContent) {
  return { 
    status: "Error",
    message: "Post content not found in current or executor node." 
  };
}

// 4. Return the cleaned-up data
return {
  final_post: postContent,
  platform: "LinkedIn",
  word_count: postContent.split(/\s+/).length,
  ready_to_publish: true
};

// Get the count from the incoming data, or start at 0
let previousCount = $json.count || 0;

return {
  ...$json, // This carries over the post, tone, hook, etc.
  count: previousCount + 1
};
